#import "PVXCommon.h"
#import <sys/stat.h>
#import <unistd.h>

static dispatch_queue_t PVXDiagQueue;
static dispatch_once_t PVXDiagOnce;
static void PVXDiagSetup(void){dispatch_once(&PVXDiagOnce,^{PVXDiagQueue=dispatch_queue_create("com.crctdd.pyvideo.diagnostics",DISPATCH_QUEUE_SERIAL);});}
static NSString *PVXDiagSafe(NSString *s){if(!s.length)return @"";return [s stringByReplacingOccurrencesOfString:@"\r" withString:@" "];}
static NSString *PVXDiagPath(void){NSString *root=PVXStateRoot();if(!root.length)return nil;NSString *dir=[root stringByAppendingPathComponent:@"plus-diagnostics"];[[NSFileManager defaultManager]createDirectoryAtPath:dir withIntermediateDirectories:YES attributes:@{NSFilePosixPermissions:@0700} error:nil];return [dir stringByAppendingPathComponent:@"events.jsonl"];}
static NSDictionary *PVXDiagRedact(NSDictionary *fields){NSMutableDictionary *out=[NSMutableDictionary dictionary];for(NSString *key in fields){id value=fields[key];if([key.lowercaseString containsString:@"cookie"]||[key.lowercaseString containsString:@"authorization"]||[key.lowercaseString containsString:@"token"]||[key.lowercaseString containsString:@"password"]){out[key]=@"<redacted>";}else if([value isKindOfClass:NSString.class]){NSString *s=PVXDiagSafe(value);out[key]=s.length>8192?[s substringToIndex:8192]:s;}else if([value isKindOfClass:NSNumber.class]||[value isKindOfClass:NSNull.class])out[key]=value;else if([value isKindOfClass:NSDictionary.class])out[key]=PVXDiagRedact(value);else if([value isKindOfClass:NSArray.class])out[key]=value;}return out;}
void PVXDiagEvent(NSString *component,NSString *event,NSDictionary *fields){PVXDiagSetup();NSDictionary *payload=@{ @"ts":@(NSDate.date.timeIntervalSince1970), @"pid":@(getpid()), @"component":component?:@"unknown", @"event":event?:@"unknown", @"fields":PVXDiagRedact(fields?:@{})};dispatch_async(PVXDiagQueue,^{NSString *path=PVXDiagPath();if(!path.length)return;NSData *data=[NSJSONSerialization dataWithJSONObject:payload options:0 error:nil];if(!data)return;NSMutableData *line=[data mutableCopy];[line appendBytes:"\n" length:1];NSFileHandle *h=[NSFileHandle fileHandleForWritingAtPath:path];if(!h){[[NSFileManager defaultManager]createFileAtPath:path contents:nil attributes:@{NSFilePosixPermissions:@0600}];h=[NSFileHandle fileHandleForWritingAtPath:path];}if(!h)return;[h seekToEndOfFile];[h writeData:line];[h synchronizeFile];[h closeFile];NSDictionary *a=[[NSFileManager defaultManager]attributesOfItemAtPath:path error:nil];if([a[NSFileSize] unsignedLongLongValue]>8ULL*1024ULL*1024){NSString *old=[path stringByAppendingString:@".1"];[[NSFileManager defaultManager]removeItemAtPath:old error:nil];[[NSFileManager defaultManager]moveItemAtPath:path toPath:old error:nil];}});}
